CREATE OR REPLACE FUNCTION process_orders()
RETURNS VOID AS $$
DECLARE
  v_count INT := 0;
  v_order orders%ROWTYPE;
  cur CURSOR FOR SELECT * FROM orders WHERE status = 'pending';
BEGIN
  OPEN cur;
  LOOP
    FETCH cur INTO v_order;
    EXIT WHEN NOT FOUND;
    v_count := v_count + 1;
    -- process v_order
  END LOOP;
  CLOSE cur;
  RAISE NOTICE 'Processed % orders', v_count;
END;
$$ LANGUAGE plpgsql;

