PL/pgSQL Exception Handling:
CREATE OR REPLACE FUNCTION safe_insert(p_id INT, p_name TEXT)
RETURNS TEXT AS $$
BEGIN
  INSERT INTO users (id, name) VALUES (p_id, p_name);
  RETURN 'OK';
EXCEPTION
  WHEN unique_violation THEN
    RETURN 'Duplicate ID';
  WHEN not_null_violation THEN
    RETURN 'Name is required';
  WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_msg = MESSAGE_TEXT,
      v_detail = PG_EXCEPTION_DETAIL;
    RAISE WARNING 'Unexpected error: %', v_msg;
    RETURN 'Error';
END;
$$ LANGUAGE plpgsql;

