CREATE OR REPLACE PROCEDURE transfer_funds(
  from_id INT, to_id INT, amount NUMERIC
)
LANGUAGE plpgsql AS $$
BEGIN
  UPDATE accounts SET balance = balance - amount WHERE id = from_id;
  UPDATE accounts SET balance = balance + amount WHERE id = to_id;
  COMMIT;  -- Only allowed in procedures, not functions
END;
$$;

CALL transfer_funds(1, 2, 500.00);

-- Procedure with multiple commits
CREATE PROCEDURE batch_process()
LANGUAGE plpgsql AS $$
DECLARE
  batch_size INT := 1000;
BEGIN
  LOOP
    UPDATE jobs SET status = 'processed'
    WHERE id IN (SELECT id FROM jobs WHERE status = 'pending' LIMIT batch_size);
    EXIT WHEN NOT FOUND;
    COMMIT;
  END LOOP;
END;
$$;

