Isolation Levels:
-- Read Committed (default)
BEGIN;
SELECT * FROM accounts WHERE id = 1;
-- Another session might update and commit between this and next statement
SELECT * FROM accounts WHERE id = 1;  -- may see different value!
COMMIT;

-- Repeatable Read
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SELECT * FROM accounts WHERE id = 1;
-- Repeat: guaranteed same snapshot
SELECT * FROM accounts WHERE id = 1;  -- same result
COMMIT;

-- Serializable
BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
COMMIT;
-- May get: ERROR: could not serialize access due to read/write dependencies

Serializable Snapshot Isolation (SSI):
-- Write skew example (SSI catches this)
-- Two doctors must be on call. Don't let both go off duty.
BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;

SELECT COUNT(*) INTO v_count FROM on_call WHERE status = 'active';

IF v_count <= 1 THEN
  RAISE EXCEPTION 'Need at least one doctor on call';
END IF;

UPDATE on_call SET status = 'off' WHERE doctor_id = 42;

COMMIT;
-- Under Repeatable Read, two sessions could both see count=2 and both update
-- Under Serializable, one will fail with serialization error

Deadlock Detection:
-- Session 1
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
-- then Session 2 updates id=2

-- Session 2
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 2;
-- then Session 1 tries to update id=2 -> deadlock!

-- Deadlock will be detected after deadlock_timeout
-- One session gets:
-- ERROR: deadlock detected
-- DETAIL: Process 12345 waits for ShareLock on transaction 678; blocked by process 678.
-- HINT: See server log for query details.

-- Retry pattern
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance - 100 WHERE id = 2;  -- Always lock in same order!

Advisory Locks:
-- Session-level advisory lock (manual release)
SELECT pg_advisory_lock(12345);
-- Critical section
SELECT pg_advisory_unlock(12345);

-- Transaction-level (auto-release)
BEGIN;
SELECT pg_advisory_xact_lock(42);
UPDATE job_queue SET status = 'running' WHERE id = 1;
COMMIT;  -- lock released

-- Try lock (non-blocking)
SELECT pg_try_advisory_lock(999);  -- returns true or false

-- Two-key variant
SELECT pg_advisory_lock(1, 2);
SELECT pg_advisory_unlock(1, 2);

-- Use case: job queue worker locking
SELECT pg_try_advisory_lock(job_id) FROM jobs LIMIT 1;

SKIP LOCKED & NOWAIT:
-- Job queue worker: pick next available job, skipping locked ones
BEGIN;

SELECT id, payload
FROM job_queue
WHERE status = 'pending'
ORDER BY priority DESC, created_at ASC
LIMIT 1
FOR UPDATE SKIP LOCKED;

-- Process the job...
UPDATE job_queue SET status = 'completed' WHERE id = ?;

COMMIT;

-- NOWAIT: fail fast if row is locked
SELECT * FROM accounts WHERE id = 1 FOR UPDATE NOWAIT;
-- ERROR: could not obtain lock on row in relation "accounts"

-- Combined
SELECT * FROM orders
WHERE id = 42
FOR NO KEY UPDATE SKIP LOCKED;

Row Locking:
BEGIN;

-- Exclusive write lock
SELECT * FROM inventory WHERE product_id = 10 FOR UPDATE;

-- Weak write (does NOT block FOR KEY SHARE)
SELECT * FROM orders WHERE id = 5 FOR NO KEY UPDATE;

-- Shared read lock
SELECT * FROM products WHERE category_id = 3 FOR SHARE;

-- Weakest read lock (only blocks FOR UPDATE on PK/FK)
SELECT * FROM users WHERE id = 42 FOR KEY SHARE;

UPDATE inventory SET qty = qty - 1 WHERE product_id = 10;

COMMIT;

-- Check locks held
SELECT pid, locktype, mode, granted FROM pg_locks
WHERE relation = 'inventory'::regclass;

Predicate Locking:
-- Only relevant under SERIALIZABLE isolation
BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;

-- Predicate lock acquired on range
SELECT COUNT(*) FROM orders WHERE created_at BETWEEN '2024-01-01' AND '2024-01-31';

-- Another session inserts into this range
INSERT INTO orders (id, created_at) VALUES (999, '2024-01-15');

-- First session re-reads (may see the same count depending on SSI)
SELECT COUNT(*) FROM orders WHERE created_at BETWEEN '2024-01-01' AND '2024-01-31';

COMMIT;
-- If the range is read and a concurrent write touches it,
-- one transaction will abort with serialization failure

