Custom Aggregate Functions:
-- Aggregate that concatenates strings with a separator
CREATE OR REPLACE FUNCTION concat_accum(state TEXT, next TEXT, delim TEXT)
RETURNS TEXT AS $$
BEGIN
  IF state IS NULL THEN
    RETURN next;
  ELSE
    RETURN state || delim || next;
  END IF;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE AGGREGATE concat_with(text, text) (
  SFUNC = concat_accum,
  STYPE = text,
  INITCOND = ''
);

SELECT dept_id, concat_with(name, ', ') AS employees
FROM employees
GROUP BY dept_id;

-- Built-in: string_agg() does this, but custom aggregates unlock any logic

